// The first-release schema is installed from an empty database. These checks
// exercise relationships that cannot be inferred from column names alone.
func TestFirstReleaseModelSchema(t *testing.T) {
	for _, backend := range registeredDrivers() {
		t.Run(backend.name, func(t *testing.T) { testFirstReleaseModelSchemaBackend(t, identityStore(t, backend.name)) })
	}
}
func testFirstReleaseModelSchemaBackend(t *testing.T, s *Store) {
	ctx := context.Background()
	exec := func(query string, args ...any) {
		t.Helper()
		if _, err := s.db.ExecContext(ctx, query, args...); err != nil {
			t.Fatalf("%s: %v", query, err)
		}
	}
	reject := func(query string, args ...any) {
		t.Helper()
		if _, err := s.db.ExecContext(ctx, query, args...); err == nil {
			t.Fatalf("accepted invalid row: %s", query)
		}
	}
	digest := strings.Repeat("a", 64)
	exec("INSERT INTO workspace(workspace_id,name) VALUES('w','w')")
	exec("INSERT INTO project(project_id,workspace_id,name) VALUES('p',(SELECT id FROM workspace WHERE workspace_id='w'),'p')")
	exec("INSERT INTO scene(workspace_id,project_id,scene_key,name) VALUES((SELECT id FROM workspace WHERE workspace_id='w'),(SELECT id FROM project WHERE project_id='p'),'recovery','Recovery')")
	exec("INSERT INTO scene(workspace_id,project_id,scene_key,name) VALUES((SELECT id FROM workspace WHERE workspace_id='w'),(SELECT id FROM project WHERE project_id='p'),'deployment','Deployment')")
	exec("INSERT INTO policy(policy_id,workspace_id,project_id,scene_key,name) VALUES('policy-1',(SELECT id FROM workspace WHERE workspace_id='w'),(SELECT id FROM project WHERE project_id='p'),'recovery','default')")
	exec("INSERT INTO policy(policy_id,workspace_id,project_id,scene_key,name) VALUES('policy-2',(SELECT id FROM workspace WHERE workspace_id='w'),(SELECT id FROM project WHERE project_id='p'),'deployment','other')")
	reject("UPDATE scene SET default_policy_id=(SELECT id FROM policy WHERE policy_id='policy-2') WHERE scene_key='recovery'")
	exec("INSERT INTO policy_revision(policy_revision_id,policy_id,revision_number,yaml,canonical_json,digest,published_at,published_by,status,updated_by,updated_at) VALUES('rev-1',(SELECT id FROM policy WHERE policy_id='policy-1'),1,'yaml','{}',$1,1,'admin','PUBLISHED','admin',1)", digest)
	exec("UPDATE policy SET active_revision_id=(SELECT id FROM policy_revision WHERE policy_revision_id='rev-1') WHERE policy_id='policy-1'")
	exec("UPDATE scene SET default_policy_id=(SELECT id FROM policy WHERE policy_id='policy-1') WHERE scene_key='recovery'")
	reject("UPDATE policy_revision SET yaml='changed' WHERE policy_revision_id='rev-1'")
	reject("DELETE FROM policy_revision WHERE policy_revision_id='rev-1'")
	reject("INSERT INTO guardrail_run(run_id,workspace_id,project_id,scene_key,policy_id,policy_revision_id,spec_digest,status,change_set_json,change_set_digest,idempotency_key,request_digest,run_ttl_seconds,deadline_at,decision_ttl_seconds,created_by,created_at) VALUES('bad',(SELECT id FROM workspace WHERE workspace_id='w'),(SELECT id FROM project WHERE project_id='p'),'deployment',(SELECT id FROM policy WHERE policy_id='policy-1'),(SELECT id FROM policy_revision WHERE policy_revision_id='rev-1'),$1,'OPEN','{}',$2,'bad',$3,86400,86401,900,'admin',1)", digest, digest, digest)
	exec("INSERT INTO guardrail_run(run_id,workspace_id,project_id,scene_key,policy_id,policy_revision_id,spec_digest,status,change_set_json,change_set_digest,idempotency_key,request_digest,run_ttl_seconds,deadline_at,decision_ttl_seconds,created_by,created_at) VALUES('run-1',(SELECT id FROM workspace WHERE workspace_id='w'),(SELECT id FROM project WHERE project_id='p'),'recovery',(SELECT id FROM policy WHERE policy_id='policy-1'),(SELECT id FROM policy_revision WHERE policy_revision_id='rev-1'),$1,'OPEN','{}',$2,'create-1',$3,86400,86401,900,'admin',1)", digest, digest, digest)
	reject("INSERT INTO submission(submission_id,run_id,submission_no,base_submission_no,idempotency_key,request_digest,payload_json,verdict,summary,finish_run,created_by,created_at) VALUES('invalid',(SELECT id FROM guardrail_run WHERE run_id='run-1'),2,0,'bad',$1,'{}','PASS','x',FALSE,'agent',2)", digest)
	exec("INSERT INTO submission(submission_id,run_id,submission_no,base_submission_no,idempotency_key,request_digest,payload_json,verdict,summary,finish_run,created_by,created_at) VALUES('sub-1',(SELECT id FROM guardrail_run WHERE run_id='run-1'),1,0,'submit-1',$1,'{}','PASS','first',FALSE,'agent',2)", digest)
	exec("INSERT INTO submission(submission_id,run_id,submission_no,base_submission_no,idempotency_key,request_digest,payload_json,verdict,summary,finish_run,created_by,created_at) VALUES('sub-2',(SELECT id FROM guardrail_run WHERE run_id='run-1'),2,1,'submit-2',$1,'{}','PASS','final',TRUE,'agent',3)", digest)
	reject("INSERT INTO submission(submission_id,run_id,submission_no,base_submission_no,idempotency_key,request_digest,payload_json,verdict,summary,finish_run,created_by,created_at) VALUES('duplicate',(SELECT id FROM guardrail_run WHERE run_id='run-1'),3,2,'submit-2',$1,'{}','PASS','duplicate',TRUE,'agent',4)", digest)
	exec("INSERT INTO evidence(submission_id,run_id,check_id,requirement_id,observed_at,query_summary,result_summary,evidence_digest) VALUES((SELECT id FROM submission WHERE submission_id='sub-2'),(SELECT id FROM guardrail_run WHERE run_id='run-1'),'check','requirement','2026-10-26T00:00:00Z','query','result',$1)", digest)
	exec("INSERT INTO evidence(submission_id,run_id,check_id,requirement_id,observed_at,query_summary,result_summary,evidence_digest) VALUES((SELECT id FROM submission WHERE submission_id='sub-2'),(SELECT id FROM guardrail_run WHERE run_id='run-1'),'check','requirement','2026-10-26T00:01:00Z','query','different result',$1)", strings.Repeat("b", 64))
	reject("INSERT INTO evidence(submission_id,run_id,check_id,requirement_id,observed_at,query_summary,result_summary,evidence_digest) VALUES((SELECT id FROM submission WHERE submission_id='sub-2'),(SELECT id FROM guardrail_run WHERE run_id='run-1'),'check','requirement','2026-10-26T00:00:00Z','query','result',$1)", digest)
	reject("UPDATE submission SET summary='changed' WHERE submission_id='sub-2'")
	exec("UPDATE guardrail_run SET status='FINISHED',result_verdict='PASS',decision_verdict='ALLOW',decision_expires_at=3+decision_ttl_seconds,finished_at=3,final_submission_id=(SELECT id FROM submission WHERE submission_id='sub-2'),latest_submission_no=2 WHERE run_id='run-1'")
	reject("UPDATE guardrail_run SET status='EXPIRED',finished_at=NULL,final_submission_id=NULL,expired_at=86401,reason_code='RUN_EXPIRED' WHERE run_id='run-1' AND status='FINISHED'")
}

package storage

import (
	"context"
	"encoding/json"
	"errors"
	"slices"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/alibaba/open-guardrail/internal/adapters/security"
	"github.com/alibaba/open-guardrail/internal/application/identity"
)

func TestAPIKeyLifecycle(t *testing.T) {
	for _, backend := range registeredDrivers() {
		t.Run(backend.name, func(t *testing.T) {
			store := identityStore(t, backend.name)
			ctx := context.Background()
			svc := service(store)
			now := time.Now().Unix()
			svc.Now = func() time.Time { return time.Unix(now, 0) }
			initialize(t, svc)
			session := login(t, svc, testPassword)
			key, err := svc.CreateAPIKey(ctx, session.Token, "cli", "RUN_ORCHESTRATOR", identity.ScopeRunsCreateWithRevision)
			if err != nil || !identity.ValidAPIKeyID(key.ID) || key.Version != 1 || key.ExpiresAt-now != identity.DefaultAPIKeyLifetimeSeconds {
				t.Fatalf("invalid issued metadata: %+v %v", key.APIKeyMetadata, err)
			}
			for _, lifetime := range []int64{0, -1, 59, identity.MaxAPIKeyLifetimeSeconds + 1} {
				if _, err := svc.IssueAPIKey(ctx, session.Token, "cli", identity.CreateAPIKeyInput{ExpiresInSeconds: &lifetime}); !errors.Is(err, identity.ErrInvalid) {
					t.Fatalf("invalid lifetime %d accepted: %v", lifetime, err)
				}
			}
			shortLifetime := int64(60)
			short, err := svc.IssueAPIKey(ctx, session.Token, "cli", identity.CreateAPIKeyInput{Role: "POLICY_PUBLISHER", ExpiresInSeconds: &shortLifetime})
			if err != nil {
				t.Fatal(err)
			}
			page, err := svc.ListAPIKeys(ctx, session.Token, "cli", "", 1)
			if err != nil || len(page.Items) != 1 || page.NextAfter == nil {
				t.Fatalf("first page: %+v %v", page, err)
			}
			second, err := svc.ListAPIKeys(ctx, session.Token, "cli", *page.NextAfter, 1)
			if err != nil || len(second.Items) != 1 || second.NextAfter != nil || second.Items[0].ID == page.Items[0].ID {
				t.Fatalf("second page: %+v %v", second, err)
			}
			metadata, _ := json.Marshal(page)
			if strings.Contains(string(metadata), key.APIKey) || strings.Contains(string(metadata), identity.Digest(key.APIKey)) || strings.Contains(string(metadata), "apiKey") {
				t.Fatal("list leaked a secret or stored hash")
			}
			if _, err := svc.ListAPIKeys(ctx, key.APIKey, "key", "", 20); !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatal("machine key listed other credentials")
			}
			if err := svc.RevokeAPIKey(ctx, key.APIKey, "key", key.ID); !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatal("machine key revoked credentials")
			}
			if _, err := svc.RotateAPIKey(ctx, key.APIKey, "key", key.ID, 1, nil); !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatal("machine key rotated credentials")
			}
			// Scope filtering remains part of the SQL boundary, independent of the caller.
			err = store.Identity().Transact(ctx, func(tx identity.Transaction) error {
				_, err := tx.APIKey(identity.User{WorkspaceID: "other", ProjectID: "other"}, key.ID)
				return err
			})
			if !errors.Is(err, identity.ErrKeyNotFound) {
				t.Fatalf("key crossed project scope: %v", err)
			}
			rotated, err := svc.RotateAPIKey(ctx, session.Token, "cli", key.ID, key.Version, nil)
			if err != nil || rotated.ID != key.ID || rotated.Version != 2 || rotated.APIKey == key.APIKey || rotated.ExpiresAt != key.ExpiresAt || !slices.Equal(rotated.Scopes, key.Scopes) {
				t.Fatalf("rotation changed identity, grants or expiry: %+v %v", rotated.APIKeyMetadata, err)
			}
			if _, err := svc.Authenticate(ctx, key.APIKey, "key"); !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatal("old secret survived rotation")
			}
			if principal, err := svc.Authenticate(ctx, rotated.APIKey, "key"); err != nil || principal.CredentialID != key.ID {
				t.Fatalf("replacement secret rejected: %v", err)
			}
			if retry, err := svc.RotateAPIKey(ctx, session.Token, "cli", key.ID, 1, nil); !errors.Is(err, identity.ErrKeyConflict) || retry.APIKey != "" {
				t.Fatal("rotation replay replaced the returned credential")
			}
			failing := identity.New(failAuditRepository{Repository: store.Identity()}, security.Passwords{})
			failing.Now = svc.Now
			if result, err := failing.RotateAPIKey(ctx, session.Token, "cli", key.ID, 2, nil); err == nil || result.APIKey != "" {
				t.Fatal("rotation returned a secret despite audit failure")
			}
			if err := failing.RevokeAPIKey(ctx, session.Token, "cli", key.ID); err == nil {
				t.Fatal("revocation succeeded despite audit failure")
			}
			if _, err := svc.Authenticate(ctx, rotated.APIKey, "key"); err != nil {
				t.Fatal("failed audit did not roll back credential changes")
			}
			renewedLifetime := identity.MaxAPIKeyLifetimeSeconds
			renewed, err := svc.RotateAPIKey(ctx, session.Token, "cli", key.ID, rotated.Version, &renewedLifetime)
			if err != nil || renewed.ExpiresAt != now+renewedLifetime || !slices.Equal(renewed.Scopes, rotated.Scopes) {
				t.Fatal("explicit lifetime changed grants or was not applied", err)
			}
			rotated = renewed
			now = short.ExpiresAt
			if _, err := svc.Authenticate(ctx, short.APIKey, "key"); !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatal("key accepted at its expiry boundary")
			}
			if _, err := svc.RotateAPIKey(ctx, session.Token, "cli", short.ID, 1, nil); !errors.Is(err, identity.ErrKeyConflict) {
				t.Fatal("rotation revived expired key")
			}
			for range 2 {
				if err := svc.RevokeAPIKey(ctx, session.Token, "cli", key.ID); err != nil {
					t.Fatal(err)
				}
			}
			if _, err := svc.Authenticate(ctx, rotated.APIKey, "key"); !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatal("revoked secret accepted")
			}
			if _, err := svc.RotateAPIKey(ctx, session.Token, "cli", key.ID, rotated.Version, nil); !errors.Is(err, identity.ErrKeyConflict) {
				t.Fatal("rotation revived revoked key")
			}
			var events int
			if err := store.db.QueryRow("SELECT COUNT(*) FROM audit_event WHERE event_type='api_key_revoked' AND resource_id=$1", key.ID).Scan(&events); err != nil || events != 1 {
				t.Fatalf("revocation replay duplicated audit: count=%d error=%v", events, err)
			}
			now += int64(identity.SessionLifetime.Seconds())
			if _, err := svc.ListAPIKeys(ctx, session.Token, "cli", "", 20); !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatal("expired administrator session listed keys")
			}
			if err := svc.RevokeAPIKey(ctx, session.Token, "cli", short.ID); !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatal("expired administrator session revoked a key")
			}
		})
	}
}

func TestConcurrentAPIKeyRotation(t *testing.T) {
	for _, backend := range registeredDrivers() {
		t.Run(backend.name, func(t *testing.T) {
			store := identityStore(t, backend.name)
			svc := service(store)
			initialize(t, svc)
			session := login(t, svc, testPassword)
			ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
			defer cancel()
			key, err := svc.CreateAPIKey(ctx, session.Token, "cli", "POLICY_PUBLISHER")
			if err != nil {
				t.Fatal(err)
			}
			type outcome struct {
				key identity.APIKeyResult
				err error
			}
			results := make(chan outcome, 4)
			start := make(chan struct{})
			var workers sync.WaitGroup
			for range 4 {
				workers.Add(1)
				go func() {
					defer workers.Done()
					<-start
					result, err := svc.RotateAPIKey(ctx, session.Token, "cli", key.ID, 1, nil)
					results <- outcome{result, err}
				}()
			}
			close(start)
			workers.Wait()
			close(results)
			winners := 0
			for result := range results {
				if result.err == nil {
					winners++
					if _, err := svc.Authenticate(ctx, result.key.APIKey, "key"); err != nil {
						t.Fatal("winning secret was replaced", err)
					}
				} else if !errors.Is(result.err, identity.ErrKeyConflict) || result.key.APIKey != "" {
					t.Fatalf("unexpected loser: %v", result.err)
				}
			}
			if winners != 1 {
				t.Fatalf("rotation winners=%d, want one", winners)
			}
		})
	}
}

func TestAPIKeyExpiryAfterConnectionWait(t *testing.T) {
	for _, backend := range registeredDrivers() {
		t.Run(backend.name, func(t *testing.T) {
			store := identityStore(t, backend.name)
			svc := service(store)
			initialize(t, svc)
			session := login(t, svc, testPassword)
			ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer cancel()
			key, err := svc.CreateAPIKey(ctx, session.Token, "cli", "RUN_ORCHESTRATOR")
			if err != nil {
				t.Fatal(err)
			}
			var now atomic.Int64
			now.Store(key.ExpiresAt - 1)
			svc.Now = func() time.Time { return time.Unix(now.Load(), 0) }
			store.db.SetMaxOpenConns(1)
			held, err := store.db.Conn(ctx)
			if err != nil {
				t.Fatal(err)
			}
			defer held.Close()
			waits := store.db.Stats().WaitCount
			result := make(chan error, 1)
			go func() { _, err := svc.Authenticate(ctx, key.APIKey, "key"); result <- err }()
			for store.db.Stats().WaitCount == waits {
				select {
				case <-ctx.Done():
					t.Fatal("authentication did not wait for the held connection")
				case <-time.After(time.Millisecond):
				}
			}
			now.Store(key.ExpiresAt)
			if err := held.Close(); err != nil {
				t.Fatal(err)
			}
			if err := <-result; !errors.Is(err, identity.ErrUnauthorized) {
				t.Fatalf("pool wait extended key lifetime: %v", err)
			}
		})
	}
}

package storage

import (
	"context"
	"errors"
	"strings"
	"testing"

	runapp "github.com/alibaba/open-guardrail/internal/application/run"
	rundomain "github.com/alibaba/open-guardrail/internal/domain/run"
	specdomain "github.com/alibaba/open-guardrail/internal/domain/spec"
)

func TestPolicyRunExpiryAndCredentialRotation(t *testing.T) {
	for _, backend := range registeredDrivers() {
		t.Run(backend.name, func(t *testing.T) { testPolicyRunExpiryAndCredentialRotationBackend(t, identityStore(t, backend.name)) })
	}
}
func testPolicyRunExpiryAndCredentialRotationBackend(t *testing.T, store *Store) {
	ctx := context.Background()
	scope := runapp.Scope{WorkspaceID: "w", ProjectID: "p", ActorID: "orchestrator"}
	canonical, specDigest, err := specdomain.Validate(sampleSpec)
	if err != nil {
		t.Fatal(err)
	}
	exec := func(q string, args ...any) {
		t.Helper()
		if _, err := store.db.ExecContext(ctx, q, args...); err != nil {
			t.Fatal(err)
		}
	}
	exec("INSERT INTO workspace(workspace_id,name) VALUES('w','w')")
	exec("INSERT INTO project(project_id,workspace_id,name) VALUES('p',(SELECT id FROM workspace WHERE workspace_id='w'),'p')")
	exec("INSERT INTO scene(workspace_id,project_id,scene_key,name,run_ttl_seconds) VALUES((SELECT id FROM workspace WHERE workspace_id='w'),(SELECT id FROM project WHERE project_id='p'),'recovery','Recovery',60)")
	exec("INSERT INTO policy(policy_id,workspace_id,project_id,scene_key,name) VALUES('pol',(SELECT id FROM workspace WHERE workspace_id='w'),(SELECT id FROM project WHERE project_id='p'),'recovery','default')")
	exec("INSERT INTO policy_revision(policy_revision_id,policy_id,revision_number,yaml,canonical_json,digest,published_at,published_by,status,updated_by,updated_at) VALUES('rev',(SELECT id FROM policy WHERE policy_id='pol'),1,$1,$2,$3,1,'admin','PUBLISHED','admin',1)", sampleSpec, canonical, specDigest)
	exec("UPDATE policy SET active_revision_id=(SELECT id FROM policy_revision WHERE policy_revision_id='rev') WHERE policy_id='pol'")
	exec("UPDATE scene SET default_policy_id=(SELECT id FROM policy WHERE policy_id='pol') WHERE scene_key='recovery'")
	digest := strings.Repeat("a", 64)
	in := runapp.PolicyRunCreateInput{SceneKey: "recovery", ChangeSetJSON: "{}", ChangeSetDigest: digest, IdempotencyKey: "create", RequestDigest: digest, SubmissionTokenHash: digest, Now: 1000}
	run, _, err := store.Runs().CreatePolicyRun(ctx, scope, in)
	if err != nil {
		t.Fatal(err)
	}
	staleSubmissionScope, err := store.Runs().AuthenticateSubmissionToken(ctx, run.ID, digest)
	if err != nil {
		t.Fatal(err)
	}
	rotated, err := store.Runs().RotatePolicySubmissionCredential(ctx, scope, run.ID, strings.Repeat("b", 64), fixedRunTime(1050))
	if err != nil || rotated.DeadlineAt != 1060 {
		t.Fatalf("rotate=%+v err=%v", rotated, err)
	}
	snapshot := rundomain.SubmissionSnapshot{BaseSubmissionNo: 0, FinishRun: false, Verdict: "PASS", Summary: "healthy", Checks: []rundomain.CheckSnapshot{{CheckID: "readiness", Verdict: "PASS", Summary: "healthy", Evidence: []rundomain.Observation{{RequirementID: "health", ObservedAt: "2026-10-26T00:00:00Z", QuerySummary: "checked health", ResultSummary: "healthy"}}}}}
	if _, _, err := store.Runs().SubmitSnapshot(ctx, staleSubmissionScope, run.ID, runapp.SnapshotSubmitInput{IdempotencyKey: "stale-credential", Snapshot: snapshot, Now: fixedRunTime(1051)}); !errors.Is(err, runapp.ErrUnauthorized) {
		t.Fatalf("stale credential submitted after rotation: %v", err)
	}
	currentSubmissionScope, err := store.Runs().AuthenticateSubmissionToken(ctx, run.ID, strings.Repeat("b", 64))
	if err != nil {
		t.Fatal(err)
	}
	accepted, created, err := store.Runs().SubmitSnapshot(ctx, currentSubmissionScope, run.ID, runapp.SnapshotSubmitInput{IdempotencyKey: "current-credential", Snapshot: snapshot, Now: fixedRunTime(1051)})
	if err != nil || !created {
		t.Fatalf("current credential submit created=%v err=%v", created, err)
	}
	thirdHash := strings.Repeat("c", 64)
	if _, err := store.Runs().RotatePolicySubmissionCredential(ctx, scope, run.ID, thirdHash, fixedRunTime(1052)); err != nil {
		t.Fatalf("second rotation: %v", err)
	}
	if _, _, err := store.Runs().SubmitSnapshot(ctx, currentSubmissionScope, run.ID, runapp.SnapshotSubmitInput{IdempotencyKey: "current-credential", Snapshot: snapshot, Now: fixedRunTime(1053)}); !errors.Is(err, runapp.ErrUnauthorized) {
		t.Fatalf("stale credential replayed after rotation: %v", err)
	}
	thirdScope, err := store.Runs().AuthenticateSubmissionToken(ctx, run.ID, thirdHash)
	if err != nil {
		t.Fatal(err)
	}
	replayed, created, err := store.Runs().SubmitSnapshot(ctx, thirdScope, run.ID, runapp.SnapshotSubmitInput{IdempotencyKey: "current-credential", Snapshot: snapshot, Now: fixedRunTime(1053)})
	if err != nil || created || replayed.ID != accepted.ID {
		t.Fatalf("current credential replay=%+v created=%v err=%v", replayed, created, err)
	}
	if _, err := store.Runs().RotatePolicySubmissionCredential(ctx, scope, run.ID, strings.Repeat("d", 64), fixedRunTime(1060)); !errors.Is(err, runapp.ErrExpired) {
		t.Fatalf("rotate after deadline=%v", err)
	}
	expired, err := store.Runs().RefreshPolicyRun(ctx, scope, run.ID, 1061)
	if err != nil || expired.Status != "EXPIRED" || expired.Decision == nil || *expired.Decision != "DENY" || expired.DecisionExpiresAt == nil || *expired.DecisionExpiresAt != 1960 {
		t.Fatalf("expired=%+v err=%v", expired, err)
	}
	if _, err := store.Runs().RotatePolicySubmissionCredential(ctx, scope, run.ID, strings.Repeat("e", 64), fixedRunTime(1062)); !errors.Is(err, runapp.ErrExpired) {
		t.Fatalf("rotate expired=%v", err)
	}
	// Submission and list expiry use the same transition, including one audit
	// event per Run, regardless of later refreshes.
	in.IdempotencyKey = "submit-expired"
	submitting, _, err := store.Runs().CreatePolicyRun(ctx, scope, in)
	if err != nil {
		t.Fatal(err)
	}
	snapshot.FinishRun = true
	submittingScope := scope
	submittingScope.SubmissionCredentialHash = in.SubmissionTokenHash
	if _, _, err := store.Runs().SubmitSnapshot(ctx, submittingScope, submitting.ID, runapp.SnapshotSubmitInput{IdempotencyKey: "late-submit", Snapshot: snapshot, Now: fixedRunTime(1060)}); !errors.Is(err, runapp.ErrExpired) {
		t.Fatalf("submit expired=%v", err)
	}
	in.IdempotencyKey = "list-expired"
	in.SubmissionTokenHash = strings.Repeat("f", 64)
	listing, _, err := store.Runs().CreatePolicyRun(ctx, scope, in)
	if err != nil {
		t.Fatal(err)
	}
	page, more, err := store.Runs().ListPolicyRuns(ctx, scope, "", "EXPIRED", 100, 0, "", 1061)
	if err != nil || more || len(page) != 3 {
		t.Fatalf("expired page=%+v more=%v err=%v", page, more, err)
	}
	for _, item := range page {
		if item.Status != "EXPIRED" || item.Decision == nil || *item.Decision != "DENY" {
			t.Fatalf("unexpected expired Run: %+v", item)
		}
	}
	// Exercise positional parameter binding with a real nonzero cursor on all backends.
	cursorAt, cursorID := int64(0), ""
	seen := map[string]bool{}
	for i := 0; i < 3; i++ {
		items, hasMore, err := store.Runs().ListPolicyRuns(ctx, scope, "recovery", "EXPIRED", 1, cursorAt, cursorID, 1062)
		if err != nil || len(items) != 1 || hasMore != (i < 2) {
			t.Fatalf("cursor page %d: %+v more=%v err=%v", i, items, hasMore, err)
		}
		if seen[items[0].ID] {
			t.Fatal("cursor repeated a Run")
		}
		seen[items[0].ID] = true
		cursorAt, cursorID = items[0].CreatedAt, items[0].ID
	}
	if _, _, err := store.Runs().ListPolicyRuns(ctx, scope, "", "EXPIRED", 100, 0, "", 1062); err != nil {
		t.Fatal(err)
	}
	for _, id := range []string{run.ID, submitting.ID, listing.ID} {
		var count int
		if err := store.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM audit_event WHERE event_type='run_expired' AND resource_type='run' AND resource_id=$1", id).Scan(&count); err != nil || count != 1 {
			t.Fatalf("Run %s expiry audit count=%d err=%v", id, count, err)
		}
	}
}

package storage

import (
	"context"
	"errors"
	"strings"
	"testing"

	"github.com/alibaba/open-guardrail/internal/application/spec"
)

func TestPolicyLifecycleTransactions(t *testing.T) {
	for _, backend := range registeredDrivers() {
		t.Run(backend.name, func(t *testing.T) { testPolicyLifecycleTransactionsBackend(t, identityStore(t, backend.name)) })
	}
}

func TestDraftPublicationChecksReviewedContentAndRetryIdentity(t *testing.T) {
	for _, backend := range registeredDrivers() {
		t.Run(backend.name, func(t *testing.T) {
			store := identityStore(t, backend.name)
			ctx := context.Background()
			for _, query := range []string{"INSERT INTO workspace(workspace_id,name) VALUES('w','w')", "INSERT INTO project(project_id,workspace_id,name) VALUES('p',(SELECT id FROM workspace WHERE workspace_id='w'),'p')"} {
				if _, err := store.db.ExecContext(ctx, query); err != nil {
					t.Fatal(err)
				}
			}
			scope := spec.Scope{WorkspaceID: "w", ProjectID: "p", ActorID: "admin"}
			repo := spec.New(store.Specs())
			initialized, _, err := repo.InitializeScene(ctx, scope, "recovery", "Recovery", "default", sampleSpec, "init")
			if err != nil {
				t.Fatal(err)
			}
			id := initialized.Policy.ID
			replacement := strings.Replace(sampleSpec, "Inspect current state", "Inspect replacement state", 1)
			if _, err := repo.SavePolicyDraft(ctx, scope, id, replacement); err != nil {
				t.Fatal(err)
			}
			if _, _, err := repo.PublishPolicyRevision(ctx, scope, id, sampleSpec, "stale", true); !errors.Is(err, spec.ErrConflict) {
				t.Fatalf("published another session's Draft: %v", err)
			}
			page, err := repo.ListPolicyRevisions(ctx, scope, id, 100, 0)
			if err != nil || len(page.Items) != 1 {
				t.Fatalf("stale publication created a Revision: %+v %v", page, err)
			}
			published, created, err := repo.PublishPolicyRevision(ctx, scope, id, replacement, "retry", true)
			if err != nil || !created || published.YAML != replacement {
				t.Fatalf("publication=%+v created=%v err=%v", published, created, err)
			}
			if _, err := repo.SavePolicyDraft(ctx, scope, id, sampleSpec); err != nil {
				t.Fatal(err)
			}
			replayed, created, err := repo.PublishPolicyRevision(ctx, scope, id, replacement, "retry", true)
			if err != nil || created || replayed.ID != published.ID {
				t.Fatalf("exact retry changed after Draft edit: %+v %v", replayed, err)
			}
			if _, _, err := repo.PublishPolicyRevision(ctx, scope, id, sampleSpec, "retry", true); !errors.Is(err, spec.ErrConflict) {
				t.Fatalf("same key accepted different reviewed content: %v", err)
			}
		})
	}
}
func testPolicyLifecycleTransactionsBackend(t *testing.T, store *Store) {
	ctx := context.Background()
	scope := spec.Scope{WorkspaceID: "w", ProjectID: "p", ActorID: "admin"}
	if _, err := store.db.ExecContext(ctx, "INSERT INTO workspace(workspace_id,name) VALUES('w','w')"); err != nil {
		t.Fatal(err)
	}
	if _, err := store.db.ExecContext(ctx, "INSERT INTO project(project_id,workspace_id,name) VALUES('p',(SELECT id FROM workspace WHERE workspace_id='w'),'p')"); err != nil {
		t.Fatal(err)
	}
	repo := spec.New(store.Specs())
	initialized, created, err := repo.InitializeScene(ctx, scope, "recovery", "Recovery", "default", sampleSpec, "init-1")
	if err != nil || !created || initialized.Policy.ActiveRevisionID == nil || initialized.Scene.DefaultPolicyID == nil {
		t.Fatalf("initialized=%+v created=%v err=%v", initialized, created, err)
	}
	repeated, created, err := repo.InitializeScene(ctx, scope, "recovery", "Recovery", "default", sampleSpec, "init-1")
	if err != nil || created || repeated.Policy.ID != initialized.Policy.ID {
		t.Fatalf("repeat=%+v created=%v err=%v", repeated, created, err)
	}
	if _, _, err := repo.InitializeScene(ctx, scope, "recovery", "Recovery", "default", sampleSpec, "init-2"); !errors.Is(err, spec.ErrSceneAlreadyInitialized) {
		t.Fatalf("second init=%v", err)
	}
	if _, err := repo.SetPolicyArchived(ctx, scope, initialized.Policy.ID, true); !errors.Is(err, spec.ErrConflict) {
		t.Fatalf("archive default=%v", err)
	}
	alternate, created, err := repo.CreatePolicy(ctx, scope, "recovery", "alternate", "policy-1")
	if err != nil || !created {
		t.Fatalf("policy=%+v created=%v err=%v", alternate, created, err)
	}
	alternateAgain, created, err := repo.CreatePolicy(ctx, scope, "recovery", "alternate", "policy-1")
	if err != nil || created || alternateAgain.ID != alternate.ID {
		t.Fatalf("replay=%+v created=%v err=%v", alternateAgain, created, err)
	}
	draft, err := repo.SavePolicyDraft(ctx, scope, alternate.ID, sampleSpec)
	if err != nil || draft.YAML != sampleSpec {
		t.Fatalf("draft=%+v err=%v", draft, err)
	}
	first, created, err := repo.PublishPolicyRevision(ctx, scope, alternate.ID, sampleSpec, "publish-draft", true)
	if err != nil || !created || (first.RevisionNumber == nil || *first.RevisionNumber != 1) {
		t.Fatalf("first=%+v created=%v err=%v", first, created, err)
	}
	if _, err := repo.SavePolicyDraft(ctx, scope, alternate.ID, "invalid: ["); err != nil {
		t.Fatal(err)
	}
	firstAgain, created, err := repo.PublishPolicyRevision(ctx, scope, alternate.ID, sampleSpec, "publish-draft", true)
	if err != nil || created || firstAgain.ID != first.ID {
		t.Fatalf("draft replay=%+v created=%v err=%v", firstAgain, created, err)
	}
	direct, created, err := repo.PublishPolicyRevision(ctx, scope, alternate.ID, sampleSpec, "publish-direct", false)
	if err != nil || !created || (direct.RevisionNumber == nil || *direct.RevisionNumber != 2) {
		t.Fatalf("direct=%+v created=%v err=%v", direct, created, err)
	}
	unchanged, err := repo.GetPolicyDraft(ctx, scope, alternate.ID)
	if err != nil || unchanged.YAML != "invalid: [" {
		t.Fatalf("direct publish changed draft: %+v %v", unchanged, err)
	}
	activated, err := repo.ActivatePolicyRevision(ctx, scope, alternate.ID, direct.ID, nil)
	if err != nil || activated.ActiveRevisionID == nil || *activated.ActiveRevisionID != direct.ID {
		t.Fatalf("activate=%+v err=%v", activated, err)
	}
	scene, err := repo.SetDefaultPolicy(ctx, scope, "recovery", alternate.ID, &initialized.Policy.ID)
	if err != nil || scene.DefaultPolicyID == nil || *scene.DefaultPolicyID != alternate.ID {
		t.Fatalf("default=%+v err=%v", scene, err)
	}
	suspended, err := repo.SavePolicyDraft(ctx, scope, initialized.Policy.ID, sampleSpec)
	if err != nil {
		t.Fatal(err)
	}
	archived, err := repo.SetPolicyArchived(ctx, scope, initialized.Policy.ID, true)
	if err != nil || archived.LifecycleState != "ARCHIVED" {
		t.Fatalf("archived=%+v err=%v", archived, err)
	}
	if _, err := repo.SavePolicyDraft(ctx, scope, archived.ID, sampleSpec); !errors.Is(err, spec.ErrConflict) {
		t.Fatalf("archived draft=%v", err)
	}
	readOnly, err := repo.GetPolicyDraft(ctx, scope, archived.ID)
	if err != nil || readOnly.ID != suspended.ID || readOnly.YAML != sampleSpec || readOnly.Status != "DRAFT" {
		t.Fatalf("archiving changed or hid draft: %+v %v", readOnly, err)
	}
	if _, _, err := repo.PublishPolicyRevision(ctx, scope, archived.ID, sampleSpec, "archived-draft", true); !errors.Is(err, spec.ErrConflict) {
		t.Fatalf("archived draft published: %v", err)
	}
	restored, err := repo.SetPolicyArchived(ctx, scope, archived.ID, false)
	if err != nil || restored.LifecycleState != "ACTIVE" {
		t.Fatalf("restored=%+v err=%v", restored, err)
	}
	replacement := strings.Replace(sampleSpec, "Inspect current state", "Inspect restored state", 1)
	resumed, err := repo.SavePolicyDraft(ctx, scope, restored.ID, replacement)
	if err != nil || resumed.ID != suspended.ID || resumed.YAML != replacement || resumed.Status != "DRAFT" {
		t.Fatalf("restoring did not resume the same draft: %+v %v", resumed, err)
	}
	var draftAudits int
	if err := store.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM audit_event WHERE event_type='policy_draft_saved' AND resource_type='revision' AND resource_id=$1", suspended.ID).Scan(&draftAudits); err != nil || draftAudits != 2 {
		t.Fatalf("draft audit must reference the edited Revision: count=%d err=%v", draftAudits, err)
	}
	ttl, err := repo.SetSceneTTL(ctx, scope, "recovery", 604800)
	if err != nil || ttl.RunTTLSeconds != 604800 {
		t.Fatalf("ttl=%+v err=%v", ttl, err)
	}
	for _, event := range []struct{ name, kind, id string }{
		{"scene_initialized", "scene", "recovery"},
		{"policy_created", "policy", alternate.ID},
		{"policy_revision_published", "revision", first.ID},
		{"policy_revision_activated", "policy", alternate.ID},
		{"scene_default_policy_changed", "scene", "recovery"},
	} {
		var count int
		if err := store.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM audit_event WHERE event_type=$1 AND resource_type=$2 AND resource_id=$3", event.name, event.kind, event.id).Scan(&count); err != nil || count != 1 {
			t.Fatalf("audit %s %s/%s count=%d err=%v", event.name, event.kind, event.id, count, err)
		}
	}
}

package storage

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"errors"
	"strconv"
	"time"

	"github.com/alibaba/open-guardrail/internal/application/identity"
	"github.com/alibaba/open-guardrail/internal/application/spec"
	specdomain "github.com/alibaba/open-guardrail/internal/domain/spec"
)

func scanSceneModel(row scanner) (spec.SceneModel, error) {
	var m spec.SceneModel
	var defaultID sql.NullString
	err := row.Scan(&m.Key, &m.Name, &defaultID, &m.RunTTLSeconds)
	if err != nil {
		return spec.SceneModel{}, specError(err)
	}
	if defaultID.Valid {
		m.DefaultPolicyID = &defaultID.String
	}
	return m, nil
}
func (s *Specs) GetSceneModel(ctx context.Context, scope spec.Scope, key string) (spec.SceneModel, error) {
	return scanSceneModel(s.db.QueryRowContext(ctx, "SELECT "+sceneModelColumns+" FROM scene WHERE workspace_id=(SELECT id FROM workspace WHERE workspace_id=$1) AND project_id=(SELECT id FROM project WHERE project_id=$2) AND scene_key=$3", scope.WorkspaceID, scope.ProjectID, key))
}
func (s *Specs) ListSceneModels(ctx context.Context, scope spec.Scope) ([]spec.SceneModel, error) {
	rows, err := s.db.QueryContext(ctx, "SELECT "+sceneModelColumns+" FROM scene WHERE workspace_id=(SELECT id FROM workspace WHERE workspace_id=$1) AND project_id=(SELECT id FROM project WHERE project_id=$2) ORDER BY scene_key", scope.WorkspaceID, scope.ProjectID)
	if err != nil {
		return nil, specError(err)
	}
	defer rows.Close()
	result := []spec.SceneModel{}
	for rows.Next() {
		scene, err := scanSceneModel(rows)
		if err != nil {
			return nil, err
		}
		result = append(result, scene)
	}
	return result, specError(rows.Err())
}
func scanPolicyModel(row scanner) (spec.Policy, error) {
	var p spec.Policy
	var activeID sql.NullString
	err := row.Scan(&p.ID, &p.SceneKey, &p.Name, &p.LifecycleState, &activeID)
	if err != nil {
		return spec.Policy{}, specError(err)
	}
	if activeID.Valid {
		p.ActiveRevisionID = &activeID.String
	}
	return p, nil
}

const policyModelColumns = "p.policy_id,p.scene_key,p.name,p.lifecycle_state,a.policy_revision_id"
const policyModelFrom = " FROM policy p LEFT JOIN policy_revision a ON a.id=p.active_revision_id"
const sceneModelColumns = "scene_key,name,(SELECT policy_id FROM policy WHERE id=scene.default_policy_id),run_ttl_seconds"

func policyByID(ctx context.Context, q rowQueryer, scope spec.Scope, id string) (spec.Policy, error) {
	return scanPolicyModel(q.QueryRowContext(ctx, "SELECT "+policyModelColumns+policyModelFrom+" WHERE p.policy_id=$1 AND p.workspace_id=(SELECT id FROM workspace WHERE workspace_id=$2) AND p.project_id=(SELECT id FROM project WHERE project_id=$3)", id, scope.WorkspaceID, scope.ProjectID))
}
func (s *Specs) GetPolicy(ctx context.Context, scope spec.Scope, id string) (spec.Policy, error) {
	return policyByID(ctx, s.db, scope, id)
}
func scanPolicyRevision(row scanner) (spec.PolicyRevision, error) {
	var r spec.PolicyRevision
	err := row.Scan(&r.ID, &r.PolicyID, &r.RevisionNumber, &r.YAML, &r.Digest, &r.PublishedAt, &r.PublishedBy, &r.Status, &r.UpdatedBy, &r.UpdatedAt)
	if err != nil {
		return spec.PolicyRevision{}, specError(err)
	}
	return r, nil
}

const revisionModelColumns = "r.policy_revision_id,p.policy_id,r.revision_number,r.yaml,r.digest,r.published_at,r.published_by,r.status,r.updated_by,r.updated_at"
const revisionModelFrom = " FROM policy_revision r JOIN policy p ON p.id=r.policy_id"

func revisionByID(ctx context.Context, q rowQueryer, scope spec.Scope, id string) (spec.PolicyRevision, error) {
	return scanPolicyRevision(q.QueryRowContext(ctx, "SELECT "+revisionModelColumns+revisionModelFrom+" WHERE r.policy_revision_id=$1 AND p.workspace_id=(SELECT id FROM workspace WHERE workspace_id=$2) AND p.project_id=(SELECT id FROM project WHERE project_id=$3)", id, scope.WorkspaceID, scope.ProjectID))
}
func (s *Specs) GetPolicyRevision(ctx context.Context, scope spec.Scope, id string) (spec.PolicyRevision, error) {
	return revisionByID(ctx, s.db, scope, id)
}
func (s *Specs) ListPolicies(ctx context.Context, scope spec.Scope, sceneKey string) ([]spec.Policy, error) {
	rows, err := s.db.QueryContext(ctx, "SELECT "+policyModelColumns+policyModelFrom+" WHERE p.workspace_id=(SELECT id FROM workspace WHERE workspace_id=$1) AND p.project_id=(SELECT id FROM project WHERE project_id=$2) AND p.scene_key=$3 ORDER BY p.policy_id", scope.WorkspaceID, scope.ProjectID, sceneKey)
	if err != nil {
		return nil, specError(err)
	}
	defer rows.Close()
	out := []spec.Policy{}
	for rows.Next() {
		p, err := scanPolicyModel(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, p)
	}
	return out, specError(rows.Err())
}
func (s *Specs) ListPolicyRevisions(ctx context.Context, scope spec.Scope, policyID string, pageSize int, before int64) (spec.RevisionPage, error) {
	if pageSize < 1 || pageSize > 100 || before < 0 {
		return spec.RevisionPage{}, spec.ErrInvalid
	}
	if _, err := policyByID(ctx, s.db, scope, policyID); err != nil {
		return spec.RevisionPage{}, err
	}
	query := "SELECT r.policy_revision_id,p.policy_id,r.revision_number,r.digest,r.published_at,r.published_by FROM policy_revision r JOIN policy p ON p.id=r.policy_id WHERE p.policy_id=$1 AND r.status='PUBLISHED'"
	args := []any{policyID}
	if before > 0 {
		query += " AND r.revision_number<$2"
		args = append(args, before)
	}
	query += " ORDER BY r.revision_number DESC LIMIT $" + strconv.Itoa(len(args)+1)
	args = append(args, pageSize+1)
	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return spec.RevisionPage{}, specError(err)
	}
	defer rows.Close()
	page := spec.RevisionPage{Items: []spec.RevisionSummary{}}
	for rows.Next() {
		var item spec.RevisionSummary
		if err := rows.Scan(&item.ID, &item.PolicyID, &item.RevisionNumber, &item.Digest, &item.PublishedAt, &item.PublishedBy); err != nil {
			return spec.RevisionPage{}, specError(err)
		}
		if len(page.Items) == pageSize {
			cursor := page.Items[len(page.Items)-1].RevisionNumber
			page.NextBefore = &cursor
			break
		}
		page.Items = append(page.Items, item)
	}
	return page, specError(rows.Err())
}
func modelDigest(v string) string { sum := sha256.Sum256([]byte(v)); return hex.EncodeToString(sum[:]) }
func recordByKey(ctx context.Context, q rowQueryer, scope spec.Scope, operation, key string) (string, string, error) {
	var digest, resourceID string
	err := q.QueryRowContext(ctx, "SELECT request_digest,resource_id FROM idempotency_record WHERE workspace_id=(SELECT id FROM workspace WHERE workspace_id=$1) AND project_id=(SELECT id FROM project WHERE project_id=$2) AND operation_type=$3 AND idempotency_key=$4", scope.WorkspaceID, scope.ProjectID, operation, key).Scan(&digest, &resourceID)
	if err != nil {
		return "", "", specError(err)
	}
	return digest, resourceID, nil
}
func insertRecord(ctx context.Context, tx *sql.Tx, scope spec.Scope, operation, key, digest, resourceType, resourceID string, now int64) error {
	_, err := tx.ExecContext(ctx, `INSERT INTO idempotency_record(workspace_id,project_id,operation_type,idempotency_key,request_digest,resource_type,resource_id,created_at)
 VALUES((SELECT id FROM workspace WHERE workspace_id=$1),(SELECT id FROM project WHERE project_id=$2),$3,$4,$5,$6,$7,$8)`, scope.WorkspaceID, scope.ProjectID, operation, key, digest, resourceType, resourceID, now)
	return specError(err)
}
func lockPolicyModel(ctx context.Context, tx *sql.Tx, scope spec.Scope, id string) (spec.Policy, error) {
	result, err := tx.ExecContext(ctx, "UPDATE policy SET lifecycle_state=lifecycle_state WHERE policy_id=$1 AND workspace_id=(SELECT id FROM workspace WHERE workspace_id=$2) AND project_id=(SELECT id FROM project WHERE project_id=$3)", id, scope.WorkspaceID, scope.ProjectID)
	if err != nil {
		return spec.Policy{}, specError(err)
	}
	n, err := result.RowsAffected()
	if err != nil {
		return spec.Policy{}, specError(err)
	}
	if n == 0 {
		return spec.Policy{}, spec.ErrNotFound
	}
	return policyByID(ctx, tx, scope, id)
}
func (s *Specs) CreatePolicy(ctx context.Context, scope spec.Scope, sceneKey, name, key string) (spec.Policy, bool, error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return spec.Policy{}, false, specError(err)
	}
	defer tx.Rollback()
	if err = lockSpecProject(ctx, tx, scope); err != nil {
		return spec.Policy{}, false, err
	}
	requestDigest := modelDigest(sceneKey + "\n" + name)
	if digest, id, err := recordByKey(ctx, tx, scope, "policy:create", key); err == nil {
		if digest != requestDigest {
			return spec.Policy{}, false, spec.ErrConflict
		}
		p, err := policyByID(ctx, tx, scope, id)
		return p, false, err
	} else if !errors.Is(err, spec.ErrNotFound) {
		return spec.Policy{}, false, err
	}
	result, err := tx.ExecContext(ctx, "UPDATE scene SET name=name WHERE workspace_id=(SELECT id FROM workspace WHERE workspace_id=$1) AND project_id=(SELECT id FROM project WHERE project_id=$2) AND scene_key=$3", scope.WorkspaceID, scope.ProjectID, sceneKey)
	if err != nil {
		return spec.Policy{}, false, specError(err)
	}
	n, err := result.RowsAffected()
	if err != nil {
		return spec.Policy{}, false, specError(err)
	}
	if n == 0 {
		return spec.Policy{}, false, spec.ErrNotFound
	}
	p := spec.Policy{ID: identity.RandomToken("pol_"), SceneKey: sceneKey, Name: name, LifecycleState: "ACTIVE"}
	if _, err = tx.ExecContext(ctx, "INSERT INTO policy(policy_id,workspace_id,project_id,scene_key,name) VALUES($1,(SELECT id FROM workspace WHERE workspace_id=$2),(SELECT id FROM project WHERE project_id=$3),$4,$5)", p.ID, scope.WorkspaceID, scope.ProjectID, sceneKey, name); err != nil {
		return spec.Policy{}, false, specError(err)
	}
	now := time.Now().Unix()
	if err = insertRecord(ctx, tx, scope, "policy:create", key, requestDigest, "policy", p.ID, now); err != nil {
		return spec.Policy{}, false, err
	}
	if err = specAudit(ctx, tx, scope, "policy_created", "policy", p.ID); err != nil {
		return spec.Policy{}, false, err
	}
	if err = tx.Commit(); err != nil {
		return spec.Policy{}, false, specError(err)
	}
	return p, true, nil
}
func draftByPolicy(ctx context.Context, q rowQueryer, scope spec.Scope, id string) (spec.PolicyRevision, error) {
	return scanPolicyRevision(q.QueryRowContext(ctx, "SELECT "+revisionModelColumns+revisionModelFrom+" WHERE p.policy_id=$1 AND r.status='DRAFT' AND p.workspace_id=(SELECT id FROM workspace WHERE workspace_id=$2) AND p.project_id=(SELECT id FROM project WHERE project_id=$3)", id, scope.WorkspaceID, scope.ProjectID))
}
func (s *Specs) GetPolicyDraft(ctx context.Context, scope spec.Scope, id string) (spec.PolicyRevision, error) {
	return draftByPolicy(ctx, s.db, scope, id)
}
func (s *Specs) SavePolicyDraft(ctx context.Context, scope spec.Scope, id, yaml string) (spec.PolicyRevision, error) {
	if len(yaml) > specdomain.MaxYAMLBytes {
		return spec.PolicyRevision{}, spec.ErrInvalid
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return spec.PolicyRevision{}, specError(err)
	}
	defer tx.Rollback()
	policy, err := lockPolicyModel(ctx, tx, scope, id)
	if err != nil {
		return spec.PolicyRevision{}, err
	}
	if policy.LifecycleState != "ACTIVE" {
		return spec.PolicyRevision{}, spec.ErrConflict
	}
	now := time.Now().Unix()
	inserted, err := tx.ExecContext(ctx, `INSERT INTO policy_revision(policy_revision_id,policy_id,status,yaml,updated_by,updated_at)
 SELECT $1,id,'DRAFT',$2,$3,$4 FROM policy WHERE policy_id=$5
 AND NOT EXISTS(SELECT 1 FROM policy_revision WHERE policy_id=policy.id AND status='DRAFT')`, identity.RandomToken("rev_"), yaml, scope.ActorID, now, id)
	if err != nil {
		return spec.PolicyRevision{}, specError(err)
	}
	count, err := inserted.RowsAffected()
	if err != nil {
		return spec.PolicyRevision{}, specError(err)
	}
	if count == 0 {
		_, err = tx.ExecContext(ctx, `UPDATE policy_revision SET yaml=$1,canonical_json=NULL,digest=NULL,updated_by=$2,updated_at=$3
 WHERE policy_id=(SELECT id FROM policy WHERE policy_id=$4) AND status='DRAFT'`, yaml, scope.ActorID, now, id)
		if err != nil {
			return spec.PolicyRevision{}, specError(err)
		}
	}
	draft, err := draftByPolicy(ctx, tx, scope, id)
	if err != nil {
		return spec.PolicyRevision{}, err
	}
	if err = specAudit(ctx, tx, scope, "policy_draft_saved", "revision", draft.ID); err != nil {
		return spec.PolicyRevision{}, err
	}
	if err = tx.Commit(); err != nil {
		return spec.PolicyRevision{}, specError(err)
	}
	return draft, nil
}
func (s *Specs) CommitPolicyRevision(ctx context.Context, scope spec.Scope, input spec.PublicationInput) (spec.PolicyRevision, bool, error) {
	if input.Now == nil {
		return spec.PolicyRevision{}, false, spec.ErrInvalid
	}
	policyID, yaml, key := input.PolicyID, input.YAML, input.IdempotencyKey
	operation, requestDigest := input.OperationType, input.RequestDigest
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return spec.PolicyRevision{}, false, specError(err)
	}
	defer tx.Rollback()
	if err = lockSpecProject(ctx, tx, scope); err != nil {
		return spec.PolicyRevision{}, false, err
	}
	if digest, id, err := recordByKey(ctx, tx, scope, operation, key); err == nil {
		if digest != requestDigest {
			return spec.PolicyRevision{}, false, spec.ErrConflict
		}
		r, err := revisionByID(ctx, tx, scope, id)
		return r, false, err
	} else if !errors.Is(err, spec.ErrNotFound) {
		return spec.PolicyRevision{}, false, err
	}
	p, err := lockPolicyModel(ctx, tx, scope, policyID)
	if err != nil {
		return spec.PolicyRevision{}, false, err
	}
	if p.LifecycleState != "ACTIVE" {
		return spec.PolicyRevision{}, false, spec.ErrConflict
	}
	// For Draft publication, yaml is the exact content the caller reviewed.
	// Compare under the Policy lock so another session cannot change what is published.
	var draft spec.PolicyRevision
	if input.FromDraft {
		draft, err = draftByPolicy(ctx, tx, scope, policyID)
		if errors.Is(err, spec.ErrNotFound) {
			return spec.PolicyRevision{}, false, spec.ErrConflict
		}
		if err != nil {
			return spec.PolicyRevision{}, false, err
		}
		if draft.YAML != yaml {
			return spec.PolicyRevision{}, false, spec.ErrConflict
		}
	}
	var last int64
	if err = tx.QueryRowContext(ctx, "SELECT COALESCE(MAX(revision_number),0) FROM policy_revision WHERE policy_id=(SELECT id FROM policy WHERE policy_id=$1) AND status='PUBLISHED'", policyID).Scan(&last); err != nil {
		return spec.PolicyRevision{}, false, specError(err)
	}
	number, now := last+1, input.Now()
	revision := spec.PolicyRevision{ID: identity.RandomToken("rev_"), PolicyID: policyID, RevisionNumber: &number, YAML: yaml, Digest: &input.SpecDigest, PublishedAt: &now, PublishedBy: &scope.ActorID, Status: "PUBLISHED", UpdatedBy: scope.ActorID, UpdatedAt: now}
	var result sql.Result
	if input.FromDraft {
		revision.ID = draft.ID
		result, err = tx.ExecContext(ctx, `UPDATE policy_revision SET status='PUBLISHED',revision_number=$1,canonical_json=$2,digest=$3,
 published_at=$4,published_by=$5,updated_at=$6,updated_by=$7
 WHERE policy_revision_id=$8 AND status='DRAFT'`, revision.RevisionNumber, input.CanonicalJSON, input.SpecDigest, revision.PublishedAt, scope.ActorID, revision.UpdatedAt, revision.UpdatedBy, revision.ID)
	} else {
		result, err = tx.ExecContext(ctx, `INSERT INTO policy_revision(policy_revision_id,policy_id,status,revision_number,yaml,canonical_json,digest,published_at,published_by,updated_at,updated_by)
 VALUES($1,(SELECT id FROM policy WHERE policy_id=$2),'PUBLISHED',$3,$4,$5,$6,$7,$8,$9,$10)`, revision.ID, policyID, revision.RevisionNumber, yaml, input.CanonicalJSON, input.SpecDigest, revision.PublishedAt, scope.ActorID, revision.UpdatedAt, revision.UpdatedBy)
	}
	if err != nil {
		return spec.PolicyRevision{}, false, specError(err)
	}
	if input.FromDraft {
		count, err := result.RowsAffected()
		if err != nil {
			return spec.PolicyRevision{}, false, specError(err)
		}
		if count != 1 {
			return spec.PolicyRevision{}, false, spec.ErrConflict
		}
	}
	if err = insertRecord(ctx, tx, scope, operation, key, requestDigest, "revision", revision.ID, *revision.PublishedAt); err != nil {
		return spec.PolicyRevision{}, false, err
	}
	if err = specAudit(ctx, tx, scope, "policy_revision_published", "revision", revision.ID); err != nil {
		return spec.PolicyRevision{}, false, err
	}
	if err = tx.Commit(); err != nil {
		return spec.PolicyRevision{}, false, specError(err)
	}
	return revision, true, nil
}
func (s *Specs) ActivatePolicyRevision(ctx context.Context, scope spec.Scope, policyID, revisionID string, expected *string) (spec.Policy, error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return spec.Policy{}, specError(err)
	}
	defer tx.Rollback()
	p, err := lockPolicyModel(ctx, tx, scope, policyID)
	if err != nil {
		return spec.Policy{}, err
	}
	if p.LifecycleState != "ACTIVE" || !sameOptionalID(p.ActiveRevisionID, expected) {
		return spec.Policy{}, spec.ErrConflict
	}
	r, err := revisionByID(ctx, tx, scope, revisionID)
	if err != nil {
		return spec.Policy{}, err
	}
	if r.PolicyID != policyID {
		return spec.Policy{}, spec.ErrNotFound
	}
	if r.Status != "PUBLISHED" {
		return spec.Policy{}, spec.ErrConflict
	}
	if _, err = tx.ExecContext(ctx, "UPDATE policy SET active_revision_id=(SELECT id FROM policy_revision WHERE policy_revision_id=$1 AND status='PUBLISHED') WHERE policy_id=$2", revisionID, policyID); err != nil {
		return spec.Policy{}, specError(err)
	}
	if err = specAudit(ctx, tx, scope, "policy_revision_activated", "policy", policyID); err != nil {
		return spec.Policy{}, err
	}
	if err = tx.Commit(); err != nil {
		return spec.Policy{}, specError(err)
	}
	p.ActiveRevisionID = &revisionID
	return p, nil
}
func sameOptionalID(a, b *string) bool {
	return a == nil && b == nil || a != nil && b != nil && *a == *b
}
func (s *Specs) SetDefaultPolicy(ctx context.Context, scope spec.Scope, sceneKey, policyID string, expected *string) (spec.SceneModel, error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return spec.SceneModel{}, specError(err)
	}
	defer tx.Rollback()
	result, err := tx.ExecContext(ctx, "UPDATE scene SET name=name WHERE workspace_id=(SELECT id FROM workspace WHERE workspace_id=$1) AND project_id=(SELECT id FROM project WHERE project_id=$2) AND scene_key=$3", scope.WorkspaceID, scope.ProjectID, sceneKey)
	if err != nil {
		return spec.SceneModel{}, specError(err)
	}
	n, err := result.RowsAffected()
	if err != nil {
		return spec.SceneModel{}, specError(err)
	}
	if n == 0 {
		return spec.SceneModel{}, spec.ErrNotFound
	}
	scene, err := scanSceneModel(tx.QueryRowContext(ctx, "SELECT "+sceneModelColumns+" FROM scene WHERE workspace_id=(SELECT id FROM workspace WHERE workspace_id=$1) AND project_id=(SELECT id FROM project WHERE project_id=$2) AND scene_key=$3", scope.WorkspaceID, scope.ProjectID, sceneKey))
	if err != nil {
		return spec.SceneModel{}, err
	}
	if !sameOptionalID(scene.DefaultPolicyID, expected) {
		return spec.SceneModel{}, spec.ErrConflict
	}
	p, err := policyByID(ctx, tx, scope, policyID)
	if err != nil {
		return spec.SceneModel{}, err
	}
	if p.SceneKey != sceneKey || p.LifecycleState != "ACTIVE" || p.ActiveRevisionID == nil {
		return spec.SceneModel{}, spec.ErrConflict
	}
	if _, err = tx.ExecContext(ctx, "UPDATE scene SET default_policy_id=(SELECT id FROM policy WHERE policy_id=$1) WHERE workspace_id=(SELECT id FROM workspace WHERE workspace_id=$2) AND project_id=(SELECT id FROM project WHERE project_id=$3) AND scene_key=$4", policyID, scope.WorkspaceID, scope.ProjectID, sceneKey); err != nil {
		return spec.SceneModel{}, specError(err)
	}
	if err = specAudit(ctx, tx, scope, "scene_default_policy_changed", "scene", sceneKey); err != nil {
		return spec.SceneModel{}, err
	}
	if err = tx.Commit(); err != nil {
		return spec.SceneModel{}, specError(err)
	}
	scene.DefaultPolicyID = &policyID
	return scene, nil
}
